/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «مقدمة في علم المنطق» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["logic"]={"id":"logic","title":"مقدمة في علم المنطق","sub":"","author":"د. نايف بن نهار","coauthors":[],"translator":"","publisher":"مؤسسة وعي للدراسات والأبحاث، دولة قطر","year":"2020","edition":"الثالثة","series":"سلسلة مقدمات العلوم","lead":"كتاب تمهيدي ميسر يعرض أهم مسائل علم المنطق في ثلاثة فصول: مقدمات منطقية، ثم التصورات، ثم التصديقات من القضايا إلى القياس والاستقراء. يميزه أن «الأمثلة الواردة في هذا الكتاب أمثلة جديدة ومرتبطة بالعلوم المعاصرة».","audience":"المبتدئون في علم المنطق حصرا، من الشباب وطلاب العلوم الشرعية والإنسانية والمعلمين","bio":"","chapters":[{"k":"c1","t":"مقدمات عن المنطق","q":"ما المنطق، ومم يتكون، وما حدود ما يقدمه لنا؟","essence":"المنطق يضبط صورة التفكير لا مادته","kw":["القواعد العقلية","التصورات والتصديقات","صورة الفكرة"],"sections":[{"t":"ما المقصود بعلم المنطق؟","pg":9,"key":"«هو قواعد عقليّة تساعد على التصوّر والاستدلال بصورة صحيحة»","p":["القواعد العقلية هي القواعد التي تسلّم بها العقول السليمة بمجرد فهمها؛ مثل: النقيضان لا يجتمعان ولا يرتفعان، والكل أكبر من الجزء، ووجوب أن يكون التعريف مساويًا للمعرَّف، وغيرها من القواعد التي سوف ندرسها في هذا الكتاب."],"items":[{"h":"القواعد العلمية ليست من المنطق","x":"هي التي تثبت بالأدلة العلمية لا بالعقل المجرد، مثل قاعدة تمدد الحديد بالحرارة وانكماشه بالبرودة."},{"h":"القواعد المعرفية ليست من المنطق","x":"مثل قاعدة «الدول الديمقراطية لا تتحارب فيما بينها»، فهي حكم معرفي توصل إليه بعض الفلاسفة السياسيين، لا قاعدة عقلية."},{"h":"الأمر الأول: التصور الصحيح","x":"إذا أردت أن تشرح معنى الربا، فالمنطق يساعدك على استخدام الطرق الصحيحة لتوضيح معناه."},{"h":"الأمر الثاني: الاستدلال الصحيح","x":"حين تدافع عن آرائك يعطيك المنطق القواعد التي تجعل استدلالك صحيحا، ويكشف لك مواطن الخلل في الاستدلال الخاطئ."}]},{"t":"مما يتكون علم المنطق؟","pg":10,"key":"«فالتصورات تنقسم إلى الكليّات الخمسة والتعريفات، والتصديقات تنقسم إلى القضايا والاستدلال.»","p":[],"items":[{"h":"المبحث الأول: التصورات","x":"«الأشياء التي تعيننا على إدراك القضايا وفهمها»."},{"h":"المبحث الثاني: التصديقات","x":"«الأشياء التي تعيننا في الحكم على القضايا بالصحة أو بالخطأ»."},{"h":"خريطة علم المنطق","x":"الكليات الخمسة تكوّن التعريفات، والقضايا تكوّن الاستدلال بنوعيه: القياس والاستقراء."}]},{"t":"ما أهمية علم المنطق؟","pg":11,"key":"«فعلم المنطق يعطيك أدوات التفكير الصحيح سواء أكان ذلك في التصورات أو في الأحكام.»","p":[],"items":[{"h":"أدوات التفكير","x":"بمبحث التعريفات نعرّف الأشياء تعريفا سليما، وبمبحث الاستدلال نستدل بصورة صحيحة."},{"h":"متغلغل في العلوم","x":"تكثر مصطلحاته في كتب علماء الشريعة، ونجد مباحثه كاملة في بعض كتب أصول الفقه والكلام."},{"h":"مصطلحات دقيقة","x":"إذا سئلت عن العلاقة بين الليبرالية والعلمانية أجاب دارس المنطق: علاقة عموم وخصوص وجهي، فيعبر بدقة عن فكرته."}]},{"t":"هل المنطق يجعل أفكارنا صحيحة؟","pg":12,"key":"«إذن علم المنطق ليس مصدرًا للأفكار، وإنما هو كاشفٌ عن صحيح الأفكار وفاسدها.»","p":["علم المنطق له علاقة بصور الأفكار، لكنه ليس له علاقة بمادة الأفكار نفسها، فالمنطق يرشدك إلى طريقة التفكير الصحيحة لكنه لا يعطيك أفكارًا صحيحة."],"items":[{"h":"مثال","x":"«أرسطو فيلسوف، وكل فيلسوف ذكي، إذن أرسطو ذكي». الشروط المنطقية متحققة، أما صحة مادة المقدمتين فلا علاقة للمنطق بها."},{"h":"الرموز","x":"يستخدم المناطقة الرموز ليتجنبوا الحكم على مادة الأفكار: (أ) تساوي (ب)، وكل (ب) تساوي (ج)، إذن (أ) تساوي (ج)."},{"h":"هل يخطئ دارس المنطق؟","x":"نعم، لا بسبب خطأ علم المنطق، بل بسبب عدم مراعاته لقواعده، كما يخطئ دارس النحو في كلامه."}]},{"t":"حكم تعلم المنطق وكفاية الكتاب","pg":13,"key":"«في المسائل التي لا نص شرعيًا فيها يكون التحريم منوطًا بالضرر»","p":["وإذا نظرنا إلى علم المنطق الخالي من المسائل الفلسفية فإننا لا نجد فيه شيئاً ضاراً."],"items":[{"h":"رأي المؤلف","x":"المنطق ينقسم إلى تصورات وتصديقات، وتعليم تعريف الأشياء والاستدلال الصحيح ليس فيه ضرر، فلا يبقى مسوغ لمنع علم المنطق شرعا."},{"h":"حدود الكتاب","x":"ليس كافيا لمن أراد الإحاطة بمسائل المنطق جميعها، لكنه كاف لمن أراد الاقتصار على أهم مسائله وتوظيفها في أفكاره."}]}],"quiz":[{"q":"«أرسطو فيلسوف، وكل فيلسوف ذكي، إذن أرسطو ذكي». ما الذي يتكفل به علم المنطق هنا؟","o":["سلامة صورة الاستدلال وترتيب مقدماته","صدق المقدمتين في الواقع الخارجي","إثبات أن أرسطو ذكي في التاريخ","إثبات أن كل فيلسوف ذكي بالضرورة"],"why":"علم المنطق له علاقة بصور الأفكار، لكنه ليس له علاقة بمادة الأفكار نفسها، فالمنطق يرشدك إلى طريقة التفكير الصحيحة لكنه لا يعطيك أفكارًا صحيحة.","pg":12},{"q":"قاعدة «الدول الديمقراطية لا تتحارب فيما بينها»: من أي نوع هي بحسب الكتاب؟","o":["حكم معرفي توصل إليه بعض الباحثين","قاعدة عقلية تسلم بها العقول السليمة","قاعدة علمية تثبت بالتجربة والاستقراء","قاعدة منطقية من شروط القياس الصحيح"],"why":"وإنما هو حكم معرفي توصل إليه بعض الفلاسفة السياسيين من خلال دراسة طبيعة النظام الديمقراطي وتاريخ العلاقات بين الدول الديمقراطية.","pg":9},{"q":"في خريطة علم المنطق، تحت أي مبحث يندرج «الاستدلال»؟","o":["التصديقات، إلى جانب القضايا","التصورات، إلى جانب التعريفات","التصورات، مع الكليات الخمسة","الدلالات، مع المفهوم والمصداق"],"why":"فالتصورات تنقسم إلى الكليّات الخمسة والتعريفات، والتصديقات تنقسم إلى القضايا والاستدلال.","pg":10},{"q":"رأيت دارسا للمنطق يخطئ في استدلاله. بماذا يفسر الكتاب ذلك؟","o":["بعدم مراعاته قواعد المنطق في كلامه","بأن قواعد المنطق نفسها ناقصة","بأن المنطق يمنحه أفكارا خاطئة","بأن المنطق علم ظني لا يفيد القطع"],"why":"لكن هذا ليس بسبب خطأ علم المنطق، بل بسبب خطأ الدارس في عدم مراعاته لقواعد المنطق في كلامه","pg":12},{"q":"على أي أساس بنى المؤلف رأيه في حكم دراسة المنطق المجرد عن الفلسفة؟","o":["التحريم منوط بالضرر ولا ضرر فيه","المنطق من إنتاج العقل المسلم","الغزالي أدخله في علم الأصول","أكثر العلماء أوجبوا تعلمه"],"why":"في المسائل التي لا نص شرعيًا فيها يكون التحريم منوطًا بالضرر، فكلّ ما هو ضار يكون محرّمًا","pg":13}]},{"k":"c2","t":"مفهوم العلم","q":"ما مراتب الإدراك، وما الفرق بين التصور والتصديق؟","essence":"ست مراتب للإدراك، وتصور يسبق التصديق","kw":["مراتب الإدراك","الجهل المركب","التصور والتصديق"],"sections":[{"t":"العلم عند المناطقة","pg":15,"key":"«العلم» عند المناطقة يعني «مطلق الإدراك»","p":["أما العلم في العلوم الأخرى فهو «الإدراك القاطع الذي لا يحتمل غيره»، فهو ليس مطلق الإدراك وإنما أعلى مراتب الإدراك."],"items":[{"h":"مراتب الإدراك","x":"أعلاها اليقين ثم الظن ثم الشك ثم الوهم ثم الجهل البسيط ثم الجهل المركب."},{"h":"دليل قرآني","x":"في قوله تعالى: «قل هل عندكم من علم فتخرجوه لنا» المقصود بالعلم أعلى مراتب الإدراك وهو اليقين، لا مطلق الإدراك."}]},{"t":"مراتب الإدراك الست","pg":16,"key":"الظن: «هو الاحتمال الراجح». والوهم: «هو الاحتمال المرجوح».","p":[],"items":[{"h":"اليقين (100%)","x":"«هو إدراك الأمر على ما هو عليه إدراكاً جازماً». مثال: الجندي يتجول في المنطقة بحثا عن العدو حتى يتيقن أنه لا وجود له."},{"h":"الظن (من 51% إلى 99%)","x":"مثال: طالب مجتهد أتوقع أن ينال امتيازا، مع احتمال ضعيف ألا يحققه."},{"h":"الشك (50%)","x":"«هو تبنّي الحياد حول مسألة ما لعدم وجود مرجّح». مثال: قرأت كتابين متعارضين عن الرأسمالية ولا تذكر من أين أتيت بالمعلومة."},{"h":"الوهم (من 1% إلى 49%)","x":"مثال: يعتقد بنسبة سبعين بالمئة أن الجامعة مفتوحة وهي في الواقع مغلقة، فهو واهم."},{"h":"الجهل البسيط (0%)","x":"«هو ألا يكون لديك تصوّر أو حكم عن شيء ما». مثال: سيارة خالد بيضاء أم سوداء؟ لا أعرف."},{"h":"الجهل المركب (أقل من صفر)","x":"«هو إدراك الشيء على خلاف ما هو عليه إدراكاً جازماً». مثال: تجزم أن الكتاب في الحقيبة، ثم تفتحها فلا تجد شيئا."}]},{"t":"الفرق بين الجهل البسيط والمركب","pg":18,"key":"«الجهل البسيط: هو أنك لا تعرف وتعرف أنك لا تعرف، والجهل المركّب: هو أنك لا تعرف ولا تعرف أنك لا تعرف.»","p":["هذا يُسمّى «جهل مركّب»، أي إنه ليس مجرد جهل بسيط بحيث إنك لا تعرف الأمر، ولكنه جهل مركّب من شيئين: الأول: أنك تعتقد جازمًا أنك تعرف. الثاني: أنّ اعتقادك في غير محلّه."],"items":[]},{"t":"أقسام العلم: التصور والتصديق","pg":20,"key":"«التصوّر»: «هو الإدراك بلا حُكم». أما التصديق: «فهو الإدراك مع حُكم».","p":["فليس المقصود بالتصديق أن تصدّق القضيّة، ولكن المقصود أن تصدر حكماً عليها سواء تكذيباً أو تصديقاً."],"items":[{"h":"مثال: اليابان متطورة","x":"تتصور اليابان والتطور والعلاقة بينهما وهذا تصور، فإن صدّقت الجملة أو كذّبتها فهذا تصديق."},{"h":"الترتيب الطبيعي","x":"التصديق لاحق للتصور، فلا بد أن يحصل التصور أولا ثم يحصل التصديق."},{"h":"جهل تصوري","x":"لا تفهم المسألة نفسها، كأن لا تعرف معنى الربا أصلا."},{"h":"جهل تصديقي","x":"تعرف معنى الربا لكن لا تدري أحرام هو أم لا، ويسمى أيضا الجهل التقييمي."}]}],"quiz":[{"q":"شخص يجزم بصحة معلومة وهي في الواقع خاطئة، ولا يعلم أنه مخطئ. ما مرتبة إدراكه؟","o":["الجهل المركب","الجهل البسيط","الوهم المرجوح","الظن الراجح"],"why":"«هو إدراك الشيء على خلاف ما هو عليه إدراكاً جازماً»","pg":18},{"q":"طالب مجتهد تتوقع نجاحه بامتياز، مع احتمال ضعيف ألا يحققه. ما مرتبة إدراكك؟","o":["الظن الراجح","اليقين الجازم","الشك المتساوي","الوهم المرجوح"],"why":"وإنما أنا فقط أظنّ أنه سيحصل على امتياز لوجود مرجّح يرجّح ذلك، وهو اجتهاده.","pg":16},{"q":"ما الفرق بين «العلم» عند المناطقة ومعناه في العلوم الأخرى؟","o":["عندهم مطلق الإدراك، وعند غيرهم أعلى مراتبه","عندهم اليقين وحده، وعند غيرهم مطلق الظن","عندهم التصديق، وعند غيرهم التصور المجرد","لا فرق، فكلاهما يعني الإدراك القاطع"],"why":"أما العلم في العلوم الأخرى فهو «الإدراك القاطع الذي لا يحتمل غيره»، فهو ليس مطلق الإدراك وإنما أعلى مراتب الإدراك.","pg":15},{"q":"سمعت عبارة «اليابان متطورة». متى تنتقل من دائرة التصور إلى التصديق؟","o":["حين تحكم على العبارة بالصدق أو الكذب","حين تتصور بلاد اليابان في ذهنك","حين تفهم معنى التطور ومدلوله","حين تدرك نسبة التطور إلى اليابان"],"why":"لكن الآن: إن صدّقتَ هذه الجملة أو كذّبتها فهذا ما يسمّى «التصديق».","pg":20},{"q":"شخص يعرف معنى الربا جيدا، لكنه لا يدري أحرام هو أم حلال. بماذا يوصف؟","o":["الجهل التصديقي","الجهل التصوري","الجهل المركب","الشك المطلق"],"why":"فأنت تعرف معنى الربا، لكن لا تدري هل هو حرام أو لا؛ في هذه الحالة تكون متصفًا بالجهل التصديقي أو الجهل التقييمي.","pg":21}]},{"k":"c3","t":"أقسام التصور والتصديق","q":"متى يكون الإدراك ضروريا، ومتى يكون نظريا؟","essence":"الضروري والنظري أمران نسبيان بين الناس","kw":["الضروري","النظري","التصديق يستدعي التصور"],"sections":[{"t":"التصور الضروري والنظري","pg":22,"key":"التصوّر الضروري: «هو التصوّر الذي لا نحتاج في إدراكه إلى تأمّل أو نظر، وإنما ندركه بالضرورة الفطرية في كلّ إنسان».","p":["وهذا ما نسمّيه «التصوّر النظري»؛ لأنه يحتاج إلى نظر وتفكّر حتى تتصوره، بعكس التصوّر الضروري، فهو يحصل في الذهن دون الحاجة إلى التفكّر والنظر، بل بمجرّد النطق به."],"items":[{"h":"السماء","x":"تتصورها بمجرد أن أنطق بها، فهو تصور ضروري."},{"h":"الميرتوقراطية","x":"تحتاج إلى أن تبحث عن المصطلح حتى تفهمه، فهو تصور نظري."},{"h":"واحد ونصف سدس الاثني عشر","x":"الأول تتصوره مباشرة، والثاني تحتاج إلى تأمل حتى تعرف أنه الواحد."}]},{"t":"التصديق الضروري والنظري","pg":24,"key":"أما التصديق النظري: «فهو الذي يحتاج إلى تأمّل ونظر وبحث، فلا يمكن لك أن تصدر حكماً بتكذيبه أو بتصديقه مباشرة».","p":[],"items":[{"h":"السماء فوقنا","x":"تحكم عليها بمجرد سماعها، فهو تصديق ضروري."},{"h":"الأرض فوقنا","x":"تحكم بخطئها فورا دون تفكير، فهو تصديق ضروري كذلك."},{"h":"العينة من الربا","x":"من لا يعرف أحكام الشريعة لا يستطيع الحكم عليها، أما المتخصص في المعاملات المالية فيجيب مباشرة."},{"h":"الواحد نصف سدس الاثني عشر","x":"لا تستطيع الحكم عليها حتى تفكر فيها، فهو تصديق نظري."}]},{"t":"قاعدة: التصديق يستدعي التصور","pg":26,"key":"يقول قطب الدين الرازي: «الجميع اتفقوا على أن التصديق يستدعي التصوّر من غير عكس».","p":["وهكذا في النقاشات كلها، لا تصدر أحكامًا وتدخل منطقة التصديق إلا بعد أن تضمن أنك مررت بمرحلة التصور وأن الطرف الآخر متفق معك على التصور."],"items":[{"h":"مثال: هل علم المنطق حرام؟","x":"لا تنتقل إلى التصديق إلا بعد أن تسأله: ماذا تقصد بعلم المنطق؟ المنطق الصوري أم الفلسفة؟"}]},{"t":"نسبية الحكم بالضروري والنظري","pg":27,"key":"«إذن، قد يكون الأمر ضرورياً عند شخص ونظرياً عند آخر، وليس دائماً يكون الضروري والنظري مطّردين عند جميع الناس.»","p":[],"items":[{"h":"الأوليغاركية","x":"تصور نظري عند غير المختص بالسياسة، وتصور ضروري عند المطلع عليها."},{"h":"ابن قدامة ليس حنبليا","x":"العارف بالفقه يحكم فورا بخطئها، ومن لا يعرف التراث الفقهي يحتاج إلى بحث."},{"h":"قول ابن تيمية","x":"«كون القضية أولية ونظرية هو من الأمور الإضافية، فقد تكون بديهية لزيد نظرية لعمرو»."}]}],"quiz":[{"q":"عبارة «الأرض فوقنا»: كيف نحكم عليها؟","o":["تصديق ضروري بخطئها","تصديق نظري بخطئها","تصور ضروري لا حكم فيه","تصديق نظري بصحتها"],"why":"لن تحتاج إلى وقت كي تفكّر في الجواب وتجيبني بأنها قضيّة غير صحيحة، وإنما الجواب موجود في ذهنك بالضرورة.","pg":24},{"q":"سمع شخص لفظ «الميرتوقراطية» فاحتاج إلى بحث حتى فهمه. ما نوع إدراكه هذا؟","o":["تصور نظري","تصور ضروري","تصديق نظري","تصديق ضروري"],"why":"وهذا ما نسمّيه «التصوّر النظري»؛ لأنه يحتاج إلى نظر وتفكّر حتى تتصوره","pg":22},{"q":"سألك محاورك: هل علم المنطق حرام؟ ما أول خطوة يقترحها الكتاب؟","o":["أن تتفقا على المقصود بعلم المنطق","أن تصدر حكمك بالتحريم أو الإباحة","أن تبحث عن أدلة التحريم في الكتب","أن ترفض السؤال لأنه غير منطقي"],"why":"لا بد من الرجوع إلى منطقة التصور، لنرى هل نحن متفقون على المقصود بعلم المنطق أم لا","pg":26},{"q":"عبارة «ابن قدامة ليس حنبليا» يحكم عليها الفقيه بالخطأ فورا، ويتوقف فيها غيره. ماذا نستنتج؟","o":["أن الضروري والنظري أمران نسبيان","أن العبارة تصور وليست تصديقا","أن التصديق لا يحتاج إلى تصور","أن العبارة ضرورية عند الجميع"],"why":"إذن، قد يكون الأمر ضرورياً عند شخص ونظرياً عند آخر، وليس دائماً يكون الضروري والنظري مطّردين عند جميع الناس.","pg":27},{"q":"أي العبارات الآتية صحيحة في علاقة التصور بالتصديق؟","o":["كل تصديق يسبقه تصور، ولا عكس","كل تصور يسبقه تصديق، ولا عكس","التصور والتصديق لا يتلازمان أبدا","يصح التصديق قبل التصور أحيانا"],"why":"«الجميع اتفقوا على أن التصديق يستدعي التصوّر من غير عكس»","pg":26}]},{"k":"c4","t":"الدلالات","q":"كيف يدلنا شيء على شيء آخر، وكيف تدل الألفاظ على معانيها؟","essence":"دال ومدلول، وثلاث دلالات للفظ","kw":["الدال والمدلول","المطابقة والتضمن","الالتزام"],"sections":[{"t":"معنى الدلالة","pg":28,"key":"«الدلالة هي أن يكون الشيء بحالة يلزم من العلم بها العلم بشيء آخر.»","p":["هنا لدينا «دال» وهو العلامة الزرقاء، ولدينا «مدلول» وهو التوثيق، ومعرفتنا بأن العلامة الزرقاء تدل على التوثيق تسمّى «دلالة»."],"items":[{"h":"غياب الشمس","x":"حين تغيب الشمس يباح الإفطار: الدال غياب الشمس، والمدلول إباحة الإفطار."},{"h":"الأذان وغير المسلم","x":"جهل غير المسلم بدلالة الأذان لا ينفي وجودها، فالدلالة باقية ومعتبرة بحق العارف بها."}]},{"t":"أنواع الدلالة الأربعة","pg":29,"key":"«لدينا أربعة احتمالات: إما أن يدلنا بطريق العقل أو الطبع أو الشرع أو الوضع.»","p":[],"items":[{"h":"الدلالة العقلية","x":"«هي أن نفهم بواسطة العقل أن هذا الشيء يدلّنا على ذلك الشيء». مثال: الإفطار المعد على الطاولة يدل على وجود من أعده."},{"h":"الدلالة الطبيعية","x":"«تعني أن الطبع يخبرنا أن هذا الشيء يدلنا على ذلك الشيء». مثال: التثاؤب يدل على النوم، واحمرار الوجه على الحرج."},{"h":"الدلالة الشرعية","x":"«هي أن يدلّ شيءٌ على شيءٍ آخر من خلال إخبار الدين بذلك». مثال: طلوع الفجر يدل على وجوب صلاة الفجر، والبلوغ على التكليف."},{"h":"الدلالة الوضعية","x":"«التي وضعها الناس»، وهي غير لفظية كإشارات المرور، أو لفظية وهي التي يركز عليها المناطقة."}]},{"t":"الدلالة الوضعية اللفظية","pg":33,"key":"«لكن وضع الألفاظ بإزاء المعاني ليس على درجة واحدة، فأحياناً يكون اللفظ مطابقاً للمعنى تمام المطابقة، وأحياناً يكون دالاً على جزء من أجزاء المعنى فقط، وأحياناً يكون دالاً على شيء خارج المعنى لكنه لازم له.»","p":[],"items":[{"h":"دلالة المطابقة","x":"«أن اللفظ يطابق كل معناه مطابقة تامة». مثال: لفظ «المتنبي» يدل على الشاعر بأكمله، و«القرآن الكريم» يدل على كتاب الله كله."},{"h":"دلالة التضمن","x":"«تعني أنّ اللفظ يدل على جزء معناه، ولا يدلّ على كلّ المعنى». مثال: «يجعلون أصابعهم في آذانهم» والمقصود الأنامل، وقولك: هذا المنزل ليس جميلا، وتقصد مظهره."},{"h":"دلالة الالتزام","x":"«أنّ اللفظ يدل على معنى معيّن وفي الوقت نفسه يدلّ على معنى آخر لازم له». مثال: «خالد أعمى» يستلزم أنه قابل للبصر، و«مكيافيللي» يستلزم الحيل والخداع، و«غاندي» يستلزم التسامح."}]}],"quiz":[{"q":"ترى العلامة الزرقاء بجانب اسم حساب في تويتر فتعلم أنه موثق. ما الدال وما المدلول؟","o":["الدال العلامة، والمدلول التوثيق","الدال التوثيق، والمدلول العلامة","الدال الحساب، والمدلول صاحبه","الدال تويتر، والمدلول العلامة"],"why":"هنا لدينا «دال» وهو العلامة الزرقاء، ولدينا «مدلول» وهو التوثيق، ومعرفتنا بأن العلامة الزرقاء تدل على التوثيق تسمّى «دلالة».","pg":28},{"q":"تدخل المطبخ فترى الإفطار جاهزا على الطاولة، فتجزم بأن أحدا أعده. ما نوع هذه الدلالة؟","o":["دلالة عقلية","دلالة طبيعية","دلالة شرعية","دلالة وضعية"],"why":"أي إن العقل يخبرنا بأنه يستحيل أن يكون هذا الفعل المرتّب جاء من محض صدفة دون أن يكون من صنع الإنسان.","pg":29},{"q":"في قوله تعالى «يجعلون أصابعهم في آذانهم» المقصود الأنامل لا الأصابع كلها. ما نوع دلالة لفظ «أصابع»؟","o":["دلالة التضمن","دلالة المطابقة","دلالة الالتزام","دلالة عقلية"],"why":"فدلالة اللفظ هنا ليست دلالة مطابقة بحيث يدل على كل معناه، بل دلالته دلالة تضمنيّة، أي المقصود منه جزء المعنى وليس كله","pg":34},{"q":"كلما سمعت اسم «مكيافيللي» حضر في ذهنك معنى الحيل والخداع. ما نوع هذه الدلالة؟","o":["دلالة الالتزام","دلالة المطابقة","دلالة التضمن","دلالة طبيعية"],"why":"فكلما سمعنا اسم مكيافيللي لا نتصوّر مكيافيللي فقط، وإنما كذلك نتصوّر معنى آخر ملازماً له، وهو الحيل والخداع.","pg":35},{"q":"لماذا تعد دلالة الإشارة الحمراء على وجوب الوقوف دلالة وضعية؟","o":["لأن الناس وضعوها فتعارفوا عليها","لأن العقل يدل على وجوب الوقوف","لأن الطبع يخبرنا بمعنى اللون","لأن الشرع أخبرنا بدلالة اللون"],"why":"هل العقل أو الطبيعة أو الشرع دلّوا على ذلك؟ لا، ولكن الناس وضعوا ذلك فتعارفنا عليه.","pg":32}]},{"k":"c5","t":"المفهوم والمصداق","q":"ما الفرق بين الصورة الذهنية وتطبيقها في الواقع، وبين الكلي والجزئي؟","essence":"فرّق بين الفكرة وتطبيقها تنحل خلافات كثيرة","kw":["المفهوم","المصداق","الكلي والجزئي"],"sections":[{"t":"المفهوم والمصداق","pg":36,"key":"المقصود بالمفهوم: هو «الصورة الذهنية عن الأشياء». أما المصداق: فهو «ما ينطبق عليه المفهوم في الواقع».","p":[],"items":[{"h":"الإنسان","x":"مفهوم، وابن سينا وعمر بن الخطاب وأرسطو وغيرهم مصاديقه."},{"h":"الجمال","x":"تصورنا للجمال مفهوم، وجمال يوسف عليه السلام مصداق، أي تطبيق لمفهوم الجمال."},{"h":"الديمقراطية","x":"«النظام السياسي الذي تكون السلطة فيه بيد الشعب» مفهوم، والديمقراطية الأمريكية والفرنسية مصاديق."}]},{"t":"فائدة التفريق بين المفهوم والمصداق","pg":37,"key":"«فأحياناً تتحدث عن المفهوم والطرف الآخر يتحدث عن المصداق، ثم تكتشفان أن خلافكما وهمي لا حقيقة له.»","p":["أنّ المفهوم: هو التصوّر الذهني عن شيءٍ ما، في حين المصداق: هو التطبيق الواقعي لذلك التصوّر الذهني."],"items":[{"h":"حوار خالد وسعد","x":"خالد: الإسلام يحفظ حقوق المرأة. سعد: لأن عبد الرحمن المسلم لا يعطي زوجته حقوقها. خالد يتحدث عن المفهوم، وسعد عن المصداق."},{"h":"حوار جورج ومصطفى","x":"جورج يذم الديمقراطية لأن الأمريكي مجبر على الاختيار بين حزبين، فيناقش مصداقا واحدا، ومصطفى يمدحها مفهوما."}]},{"t":"الكلي والجزئي","pg":39,"key":"«إذن: المفهوم إذا كان صادقاً على شيء واحد يُسمّى جزئياً، وإذا كان صادقاً على أشياء كثيرة يسمّى كليًّا.»","p":[],"items":[{"h":"مفاهيم جزئية","x":"بغداد، وتويتر، وأبو بكر الصديق: كل منها لا يصدق إلا على شيء واحد."},{"h":"مفهوم كلي","x":"«كتاب» يصدق على كثيرين: كتاب السياسة لأرسطو، والأم للشافعي، والموطأ لمالك."},{"h":"القرآن الكريم","x":"جزئي مع أنه كتاب، لأنه لا يصدق إلا على كتاب واحد."}]},{"t":"درجات الكلي","pg":41,"key":"«نفهم مما مضى أنّ الكليّات ليست درجةً واحدة، وإنما هي درجاتٌ متفاوتة بحسب مستوى شمولها وعمومها.»","p":[],"items":[{"h":"المركبة","x":"تندرج تحتها السيارة والطائرة والدراجة، وتندرج تحت السيارة المرسيدس، وكلها كليات."},{"h":"البشر","x":"أعم من العلماء، والعلماء أعم من الفقهاء، والفقهاء أعم من الحنابلة."},{"h":"إضافة للمتخصصين","x":"أعرض المؤلف عن تقسيم الجزئي إلى حقيقي وإضافي، وجعل بديله أن للكلي نفسه درجات متعددة."}]}],"quiz":[{"q":"قال خالد: الإسلام يحفظ حقوق المرأة. فرد سعد: غير صحيح، لأن عبد الرحمن المسلم لا يعطي زوجته حقوقها. أين الخلل؟","o":["خالد تحدث عن المفهوم وسعد عن المصداق","خالد تحدث عن المصداق وسعد عن المفهوم","كلاهما تحدث عن المفهوم دون المصداق","كلاهما تحدث عن المصداق دون المفهوم"],"why":"هنا خالد يتحدث عن المفهوم، أي مفهوم الإسلام، في حين سعد يتحدث عن المصداق، أي عن تطبيقات الإسلام في أرض الواقع","pg":37},{"q":"لفظ «القرآن الكريم»: هل هو مفهوم كلي أم جزئي، ولماذا؟","o":["جزئي، لأنه لا يصدق إلا على كتاب واحد","كلي، لأنه يندرج تحت مفهوم الكتاب","كلي، لأن له نسخا كثيرة في العالم","جزئي، لأنه أخص من مفهوم الكتاب"],"why":"هو جزئي مع أنه كتاب كذلك، لماذا؟ لأنه لا يصدق إلا على كتاب واحد","pg":39},{"q":"رتب هذه الكليات من الأعم إلى الأخص: الحنابلة، البشر، الفقهاء، العلماء.","o":["البشر، العلماء، الفقهاء، الحنابلة","العلماء، البشر، الفقهاء، الحنابلة","البشر، الفقهاء، العلماء، الحنابلة","الحنابلة، الفقهاء، العلماء، البشر"],"why":"إذن كلّي «الحنابلة» أقل درجة وعموماً من كلّي «الفقهاء»، وكلّي «الفقهاء» أقل درجة وعموماً من كلّي «العلماء»، وكلّي العلماء أقل عموماً من كلّي «البشر»","pg":41},{"q":"حين تتحدث عن «الديمقراطية الفرنسية» فأنت تتحدث عن:","o":["مصداق الديمقراطية","مفهوم الديمقراطية","كلي الديمقراطية","تعريف الديمقراطية"],"why":"لكن حين نتحدث عن الديمقراطية الأمريكية مثلاً أو الديمقراطية الفرنسية فنحن نتحدث عن مصداق الديمقراطية وليس مفهوم الديمقراطية.","pg":37},{"q":"ذم جورج الديمقراطية لأن الأمريكي مجبر على الاختيار بين حزبين فقط. ما الرد المنطقي عليه؟","o":["هذا عيب في أحد مصاديقها لا في مفهومها","الديمقراطية مفهوم جزئي لا يصدق على كثيرين","الحزبان مصداقان متساويان في المفهوم","الشعب الأمريكي ليس مصداقا للديمقراطية"],"why":"فكان بإمكان مصطفى أن يقول لجورج: انحصار الاختيار بين حزبين عيبٌ في الديمقراطية الأمريكية وليس عيباً في النظام الديمقراطي نفسه","pg":38}]},{"k":"c6","t":"أقسام الكلي من حيث وجوده","q":"كيف ننظر إلى الكلي: ذهنا أم واقعا، وما الفرق بين الكل والكلي؟","essence":"كلي منطقي وطبيعي وعقلي، وكل يخالف الكلي","kw":["الكلي المنطقي","المتواطئ والمشكك","الكل والكلي"],"sections":[{"t":"الكلي المنطقي والطبيعي والعقلي","pg":44,"key":"«وعلم المنطق يهتم تحديداً ب «الكلّي المنطقي»؛ لأنّ علم المنطق مرتبط بالكليّات الذهنية، وليس له علاقة من حيث الأصل بالمصاديق في الواقع.»","p":[],"items":[{"h":"الكلي المنطقي","x":"النظر إلى الجمال قيمة كلية في الذهن فقط بقطع النظر عن الأشياء الجميلة. مثال: الجمال نادر."},{"h":"الكلي الطبيعي","x":"النظر إلى الأشياء الجميلة من حيث هي، بصرف النظر عن مفهوم الجمال نفسه."},{"h":"الكلي العقلي","x":"ملاحظة الأمرين معا: المفهوم ومصداقه في الواقع."},{"h":"مثال: النبي معصوم","x":"عصمة النبوة نظريا كلي منطقي، ومصاديقها كموسى وعيسى ومحمد عليهم السلام كلي طبيعي، والأمران معا كلي عقلي."}]},{"t":"المتواطئ والمشكك","pg":46,"key":"«أن المفهوم إذا كانت أفراده متساوية لا تقبل التفاوت فهو متواطئ، وإن كانت أفراده غير متساوية فهو المشكّك.»","p":[],"items":[{"h":"حي","x":"خالد حي ومحمد حي: لا يوجد شخص أكثر حياة من الآخر، فهو متواطئ."},{"h":"عالم","x":"الناس متفاوتون في العلم، بعضهم أعلم من بعض، فهو مشكك."}]},{"t":"الفرق بين الكل والكلي","pg":47,"key":"الكل: «هو حكمنا على مجموع الأفراد دون النظر إلى آحادهم». الكلي: «هو حكمنا على كلّ فرد من أفراد المجموعة».","p":["قاعدة: إذا كان الفعل يمكن أن يقوم به الفرد بصورة مستقلة فهو من باب الكلي، وإذا كان لا يمكن أن يفعله إلا بالاشتراك مع الآخرين فهو من باب الكل."],"items":[{"h":"من باب الكل","x":"هزمت المقاومة العراقية الاحتلال، وهزم برشلونة مانشستر، وحمل الأبناء أباهم، والشعب من شروط الدولة."},{"h":"من باب الكلي","x":"صافح الأبناء آباءهم: كل ابن صافح الأب بصورة مستقلة."},{"h":"فرض العين وفرض الكفاية","x":"فرض العين كالصلوات الخمس من باب الكلي، وفرض الكفاية كصلاة الجنازة من باب الكل."}]}],"quiz":[{"q":"قولنا «حمل الأبناء أباهم»: من أي باب هو؟","o":["من باب الكل","من باب الكلي","من باب الجزئي","من باب المشكك"],"why":"إذن هذا المثال من باب «الكل» وليس من باب «الكلي».","pg":47},{"q":"صلاة الجنازة فرض كفاية. من أي باب هي منطقيا؟","o":["من باب الكل، لأن المقصود مجموع المسلمين","من باب الكلي، لأن المقصود كل مسلم بعينه","من باب الجزئي، لأنها تتعلق بميت واحد","من باب المتواطئ، لأن أفرادها متساوون"],"why":"أمّا فرض الكفاية فهو من باب «الكل»؛ لأنه ليس المقصود كل فرد من أفراد المسلمين، وإنما مجموع المسلمين بلا تعيين.","pg":48},{"q":"لماذا يعد مفهوم «عالم» كليا مشككا، ومفهوم «حي» كليا متواطئا؟","o":["لأن العلم يقبل التفاوت في أفراده والحياة لا تقبله","لأن العلم يصدق على واحد والحياة تصدق على كثيرين","لأن الحياة تقبل التفاوت في أفرادها والعلم لا يقبله","لأن العلم مفهوم ذهني والحياة مصداق في الواقع"],"why":"لكن الفرق أنّ مفهوم «الحياة» لا يقبل التفاوت في أفراده، فلا يمكن أن يكون الشخص أكثر حياة من الآخر، وأما مفهوم «العلم» فهو يقبل التفاوت في أفراده","pg":46},{"q":"إذا تحدثت عن عصمة النبوة نظريا بصرف النظر عن أشخاص الأنبياء، فأي كلي هذا؟","o":["الكلي المنطقي","الكلي الطبيعي","الكلي العقلي","الكلي المشكك"],"why":"إذا كنا نتحدث عن عصمة النبوة نظرياً بصرف النظر عن أشخاص الأنبياء فهذا يسمّى «الكلّي المنطقي»","pg":45},{"q":"بأي أقسام الكلي يهتم علم المنطق تحديدا؟","o":["المنطقي المرتبط بالمفهوم وحده","الطبيعي المرتبط بالمصداق وحده","العقلي الجامع للمفهوم والمصداق","الأقسام الثلاثة بدرجة واحدة"],"why":"وعلم المنطق يهتم تحديداً ب «الكلّي المنطقي»؛ لأنّ علم المنطق مرتبط بالكليّات الذهنية","pg":45}]},{"k":"c7","t":"النسبة بين الكليات","q":"ما العلاقات الممكنة بين لفظين، وكيف نميز بينها؟","essence":"تباين وتساو وعموم مطلق أو وجهي","kw":["التباين والتساوي","العموم والخصوص","نفي العموم"],"sections":[{"t":"التباين والتساوي","pg":49,"key":"التباين: «أن اللفظ يباين اللفظ الآخر ويغايره تمام المغايرة». والتساوي: «أن اللفظين متفقان تماماً».","p":["فالقاعدة أنه إذا وجدنا لفظين كليّين لا يصدق أحدهما على الآخر فإنّ العلاقة بينهما علاقة تباين."],"items":[{"h":"تباين","x":"المسلم والمسيحي، والصيني والكويتي."},{"h":"تساو","x":"الإنسان والضاحك: فكل إنسان ضاحك وكل ضاحك إنسان، والتساوي هنا في المصداق لا في المفهوم."},{"h":"تساو آخر","x":"النبي والمعصوم: لا يوجد نبي إلا وهو معصوم، ولا يوجد بشر معصوم إلا وهو نبي."}]},{"t":"العموم والخصوص المطلق والوجهي","pg":51,"key":"«فالفرق إذن، أنّه في حالة العموم والخصوص المطلق تقبل إحدى الجملتين أن تكون كليّة، ولا تقبل الأخرى. أما العموم والخصوص الوجهي فكلتا الجملتين لا تقبلان الكليّة، ولكن يقبلان التبعيض.»","p":[],"items":[{"h":"العموم والخصوص المطلق","x":"«أن يكون أحد اللفظين أعمَّ من الآخر من كل الوجوه». مثال: العربي والخليجي، والعملة والدينار."},{"h":"العموم والخصوص الوجهي","x":"«بأن يكون أحد اللفظين أعم من الآخر من وجه، ولكنه أخص منه من وجه آخر». مثال: المسلم والعربي."},{"h":"اختبار سريع","x":"نقول: كل سوري عربي، ولا نقول: كل عربي سوري، فهو مطلق. ولا نقول: كل المسلمين عرب، ولا: كل العرب مسلمون، فهو وجهي."}]},{"t":"علاقة الجزئي بالجزئي وبالكلي","pg":54,"key":"«إذن العلاقة بين الجزئي والكلّي إما أن تكون علاقة عموم وخصوص مطلق مثل «الإسلام والدين»، أو علاقة تباين «بغداد والدين».»","p":[],"items":[{"h":"جزئي وجزئي","x":"لا تكون بينهما إلا علاقة التباين، مثل الشافعي وأرسطو، والشافعي والمتنبي."},{"h":"جزئي وكلي","x":"تباين مثل الشافعي والشجر، أو عموم وخصوص مطلق مثل الشافعي والإنسان."},{"h":"كلي وكلي","x":"تحتمل العلاقات الأربع: الإنسان والبشر، والمسلم والمسيحي، والسعودي والخليجي، والمسلم والعربي."}]},{"t":"الفرق بين عموم النفي ونفي العموم","pg":56,"key":"قاعدة: «إذا كانت الجملة مبدوءة بأداة العموم مثل «كل» فهي من باب عموم النفي، وإذا كانت مبدوءة بأداة النفي مثل «ليس» فهي من باب نفي العموم.»","p":[],"items":[{"h":"ليس كل علم نافعا","x":"نفي للعموم: يوجد بعض العلوم غير النافعة."},{"h":"كل علم ليس نافعا","x":"عموم للنفي: لا يوجد علم نافع."},{"h":"تفكير الإنسان ليس صحيحا دائما","x":"من باب نفي العموم، لأن أداة النفي «ليس» تقدمت على أداة العموم «دائما»."}]}],"quiz":[{"q":"ما العلاقة بين لفظي «المسلم» و«العربي»؟","o":["عموم وخصوص وجهي","عموم وخصوص مطلق","تساو تام في المصداق","تباين تام في المصداق"],"why":"فقد يكون المسلم غير عربي، كمسلمي إيران وأفغانستان وغيرهما، وقد يكون العربي غير مسلم، كأنْ يكون مسيحياً أو يهودياً أو ملحداً، لكن قد يكون المسلم عربياً.","pg":51},{"q":"نقول: «كل سوري عربي»، ولا نقول: «كل عربي سوري». ما العلاقة بين اللفظين؟","o":["عموم وخصوص مطلق","عموم وخصوص وجهي","تساو في المفهوم","تباين في المصداق"],"why":"فحين تقبل الجملة أن تكون كليّة ولكنها لا تقبل أن تكون كليّة حين نعكسها، فالعلاقة حينئذ علاقة عموم وخصوص مطلق.","pg":52},{"q":"ما العلاقة بين «الإنسان» و«الضاحك»؟","o":["تساو في المصداق مع اختلاف المفهوم","تساو في المفهوم مع اختلاف المصداق","عموم وخصوص مطلق من كل الوجوه","تباين، لأن مفهوميهما مختلفان"],"why":"في هذا المثال نجد أنّ المفهومين مختلفان، فمفهوم الإنسان مختلف عن مفهوم الضحك، لكن على أرض الواقع نجدهما متساويين","pg":50},{"q":"قال معلم: «كل الطلاب ليسوا ناجحين». ما المعنى بحسب قاعدة الكتاب؟","o":["نفي النجاح عن جميع الطلاب","نجاح بعض الطلاب دون بعض","نفي أن يكون كل الطلاب ناجحين","نجاح أكثر الطلاب لا جميعهم"],"why":"نحكم مباشرة على هذه الجملة بأنها من باب «عموم النفي»، لماذا؟ لأنها مبدوءة بأداة العموم «كل».","pg":56},{"q":"ما العلاقة الممكنة بين المفهومين الجزئيين «الشافعي» و«أرسطو»؟","o":["التباين فقط","التساوي فقط","العموم المطلق","العموم الوجهي"],"why":"ما العلاقة الوحيدة التي يمكن أن تكون بين الشافعي وأرسطو؟ الجواب: علاقة التباين.","pg":54}]},{"k":"c8","t":"الكليات الخمسة","q":"ما الكليات الخمسة، ولماذا نحتاج إليها في صناعة التعريف؟","essence":"جنس ونوع وفصل وعرض عام وخاصة","kw":["الجنس والنوع","الفصل","العرض العام والخاصة"],"sections":[{"t":"فائدة الكليات الخمسة","pg":59,"key":"«نصنع التعريف من خلال استعمال هذه الكليات الخمسة وتوظيفها، فإذا فهمنا هذه الكليات جيداً فإننا نستطيع أن نصنع التعاريف بصورة دقيقة ويسيرة.»","p":[],"items":[{"h":"الكليات الخمسة","x":"الجنس، والنوع، والفصل، والخاصة، والعرض العام."},{"h":"موقعها","x":"التصورات نصل إليها من خلال التعريف، والتعريف يصنع من هذه الكليات."}]},{"t":"الجنس والنوع والفصل","pg":60,"key":"الجنس: «هو الكلّي الذي يصدق على أفراد مختلفة الحقائق». النوع: «هو المفهوم الكلي الذي يتفق أفراده في الحقيقة».","p":["الفصل أقل عمومية من الجنس والنوع، فالجنس هو الأعم مطلقاً، ثم يأتي بعده النوع، ثم يأتي بعده الفصل."],"items":[{"h":"أمثلة الجنس","x":"الخشب (طاولة وباب وعصا)، والمؤسسة التعليمية (جامعة ومدرسة وروضة)، والحيوان (إنسان وحصان ونبات)."},{"h":"أمثلة النوع","x":"الجامعة: عامة ومتخصصة وحكومية وخاصة، كلها متفقة في حقيقتها. والإنسان: المتنبي والشافعي وأرسطو."},{"h":"الفصل","x":"«هو المفهوم الكلي الذي يميّز النوع عن بقية الأنواع». مثال: «الوطنية» في «جامعة قطر الوطنية»."}]},{"t":"العرض العام والخاصة","pg":62,"key":"العرض العام: «هو الكلي الذي ليس من ماهية الشيء وإنما يعرض عليه وعلى غيره».","p":["الخاصة مثل العرض العام، من حيث إنها غير متعلقة بماهيّة الشيء، لكن الفرق بينها وبين العرض العام أن العرض العام غير مختص بماهيّة محددة، في حين الخاصة مختصّة بماهيّة واحدة."],"items":[{"h":"الماهية والعوارض","x":"الإنسان مفكر: التفكير من ماهيته. الإنسان يمشي: المشي يعرض عليه ثم ينتهي."},{"h":"عرض عام","x":"المشي والأكل للإنسان والبهائم، والإجازات للجامعة والمدرسة والوزارة."},{"h":"خاصة","x":"الضحك خاص بالإنسان، وتدريس البكالوريوس خاص بالجامعة."}]},{"t":"الكليات أمور إضافية","pg":64,"key":"«الكليّات الخمس أمورٌ إضافية»","p":["فحين نصف مفهوماً معيناً بأنه «جنس» أو «نوع» فإنَّ ذلك أمر نسبي، يختلف باختلاف الموضوع المضاف إليه."],"items":[{"h":"الإنسان","x":"نوع من أنواع الحيوان، وجنس تندرج تحته أنواع مختلفة: الإنسان العربي والفارسي والأوروبي."}]}],"quiz":[{"q":"في عبارة «جامعة قطر الوطنية»، ما وظيفة كلمة «الوطنية» بين الكليات الخمسة؟","o":["فصل يميز النوع عن بقية أنواعه","جنس يصدق على أفراد مختلفة","عرض عام يعرض عليها وعلى غيرها","نوع يتفق أفراده في الحقيقة"],"why":"ولذلك نسمّي كلمة «الوطنية» فصل؛ لماذا؟ لأنها ميّزت جامعة قطر عن سواها.","pg":61},{"q":"الإجازات والعطلات في الجامعة: ما موقعها من الكليات الخمسة؟","o":["عرض عام يعرض على الجامعة وغيرها","خاصة لا توجد إلا في الجامعة","فصل يميز الجامعة عن المدرسة","جزء من ماهية الجامعة وحقيقتها"],"why":"وبناءً على ذلك، تكون «الإجازات» عَرَض عام؛ لأنه يعرض على الجامعة وعلى غيرها.","pg":63},{"q":"«تدريس مرحلة البكالوريوس» بالنسبة إلى الجامعة:","o":["خاصة بها، إذ لا تدرسه مؤسسة غيرها","عرض عام يعرض عليها وعلى غيرها","جنس يصدق على مؤسسات مختلفة","من عوارضها المؤقتة كالإجازات"],"why":"هو خاصّة في الجامعة؛ لأنه لا توجد ماهيّة أخرى غير الجامعة تدرّس البكالوريوس.","pg":63},{"q":"لماذا يعد مفهوم «الحيوان» جنسا؟","o":["لأنه يصدق على كثيرين مختلفين في الحقيقة","لأنه يصدق على أفراد متفقين في الحقيقة","لأنه يميز الإنسان عن بقية الأنواع","لأنه يعرض على الإنسان ثم ينتهي"],"why":"مفهوم الحيوان يعدُّ جنساً، لماذا؟ لأنّه مفهوم يصدق على كثيرين مختلفين في الحقيقة","pg":60},{"q":"«الإنسان» نوع بالنسبة إلى الحيوان، وجنس بالنسبة إلى الإنسان العربي والفارسي. ماذا يبين هذا؟","o":["أن وصف الكلي بالجنس أو النوع أمر نسبي","أن الإنسان جنس عال لا جنس فوقه","أن النوع والجنس لفظان مترادفان","أن الكليات لا تصلح في صناعة التعريف"],"why":"فحين نصف مفهوماً معيناً بأنه «جنس» أو «نوع» فإنَّ ذلك أمر نسبي، يختلف باختلاف الموضوع المضاف إليه.","pg":64}]},{"k":"c9","t":"المعرفات","q":"كيف نصنع تعريفا سليما، وما العيوب التي تفسده؟","essence":"خمس طرق للتعريف، ولكل طريقة شروطها","kw":["جامع مانع","الدور","التعريف بالقسمة"],"sections":[{"t":"المعيار العام وطرق التعريف","pg":65,"key":"«المعيار العام للتعريف السليم هو ألا يأتي في ذهن الشخص صورة أخرى غير صورة المعرَّف.»","p":[],"items":[{"h":"الطرق الخمس","x":"التعريف بالشرح، وباللفظ، وبالمثال، وبالحس، وبالقسمة."}]},{"t":"التعريف بالشرح","pg":66,"key":"التعريف بالشرح يعني «استعمال عدة ألفاظ لإيضاح المعرَّف، وكل لفظ يُوضَع في التعريف يجب أن يكون احترازاً من معانٍ أخرى».","p":["إذن من خلال ما مضى ندرك أن التعريف السليم منطقياً هو الذي يجعل المتلقّي لا يتصوّر في ذهنه غير المعرَّف."],"items":[{"h":"قطر دولة عربية خليجية شبه جزيرة","x":"«دولة» احتراز من المنظمات الدولية، و«عربية» من الدول غير العربية، و«خليجية» من العربية غير الخليجية، و«شبه جزيرة» من دول الخليج الأخرى."},{"h":"الديمقراطية","x":"نظام سياسي تكون السلطة فيه بيد الشعب: «نظام» جنس، و«سياسي» احتراز من النظم الاقتصادية، و«السلطة فيه بيد الشعب» احتراز من النظام الثيوقراطي."}]},{"t":"شروط التعريف بالشرح","pg":68,"key":"الدور هو: «توقّف وجود الشيء على ما يتوقف وجوده عليه».","p":[],"items":[{"h":"أن يكون جامعا","x":"يجمع جميع أفراد المعرَّف. خطأ: الإنسان «حيوان شاعر»، والقتل «إزهاق الروح بالسكين»، والمصرف «المؤسسة المالية التي تقوم على القروض»."},{"h":"أن يكون مانعا","x":"يمنع دخول ما ليس منه. خطأ: المصرف «المؤسسة المالية»، والإسلام «الدين السماوي»."},{"h":"ألا يكون فيه تكرار","x":"خطأ: الليبرالية الاقتصادية «المذهب الذي يقوم على الرأسمالية ويحد من تدخل الدولة»، فالرأسمالية تغني عن الباقي."},{"h":"ألا يذكر المعرَّف في التعريف","x":"خطأ: الإجارة «أن يؤجر الإنسان شيئا»، ويجوز إدخال جزء من المعرَّف إذا كان معلوما كالمصرف في «المصرف الإسلامي»."},{"h":"ألا يكون فيه دور","x":"مثال: تعريف الخاتم بالحَبْر والحبر بالخاتم، فيتوقف كل منهما على الآخر."},{"h":"تنبيه","x":"لا يصح إدخال «أو» التشكيكية في التعريف، لأنها تدل على التردد فلا تضيف شيئا."}]},{"t":"التعريف باللفظ","pg":75,"key":"«إذن التعريف بالأخص أو بالأعم أو بالأخفى كلُّ ذلك يعدُّ عيباً ونقصاً يجب تفاديه عند التعريف باللفظ.»","p":[],"items":[{"h":"ألا يكون اللفظ الشارح أعم","x":"الهاتف النقال «جهاز» خطأ، فالفاكس والطابعة أجهزة."},{"h":"ألا يكون أخص","x":"الهاتف النقال «آيفون» خطأ، والصواب «الجوال» لأنه مساو له."},{"h":"أن يكون أوضح وأظهر","x":"الطبقة الكادحة «البروليتاريا» خطأ لأنه أغمض، والصواب «طبقة العمال»."},{"h":"مثال جامع","x":"القرآن الكريم «كتاب» أعم، و«سورة البقرة» أخص، و«الفرقان» أخفى."}]},{"t":"التعريف بالمثال والحس","pg":79,"key":"«إذن: قد يكون التعريف بالمثال أولى وأوجب من التعريف بالشرح؛ لكونه أكثر تأثيراً في النفس، أو سيجعل الأمر أكثر وضوحاً عند السامع.»","p":[],"items":[{"h":"بالمثال","x":"الفعل: أكل وضرب ونام، والدولة: بريطانيا وفرنسا وألمانيا. والأفضل أن تذكر التعريف بالشرح ثم تنتقل إلى الأمثلة."},{"h":"بالحس","x":"أن تعطي من سألك عن القرآن مصحفا، أو تدعو صديقك إلى مطعم يقدم «المنسف»."},{"h":"مكانه في المنطق","x":"ليس للمنطق اهتمام بالتعريف بالحس، لأنه علم يتعامل مع المعاني، وذُكر إكمالا للتقسيم."}]},{"t":"التعريف بالقسمة","pg":81,"key":"«مِن خلال ما مضى يتبيّن لنا: أنّ التقسيم الذي لا تترتب عليه فائدة وثمرة يكون تقسيماً غير معتبر.»","p":[],"items":[{"h":"الأركان","x":"المقسم «هو الشيء الذي تُقسّمه إلى عدة أقسام»، والقسم «هو الشيء المتفرّع عن المقسم»، والقسيم «هو المفهوم الموازي للقسم في تفرّعهما عن المقسم»، والقسمة «هي عمليّة التقسيم نفسها»."},{"h":"نوعا القسمة","x":"عقلية يمنع العقل فيها قسما ثالثا: الإنسان إما حي أو ميت. واستقرائية بحسب الواقع: الإنسان أبيض أو أسمر أو أسود أو أصفر."},{"h":"أن تكون للتقسيم فائدة","x":"القروض إنتاجية واستهلاكية تقسيم مفيد، أما قروض عملاء سود وبيض فلا ثمرة له."},{"h":"أن تكون الأقسام متباينة","x":"علم المعاني جزء من البلاغة فلا يجعل قسيما لها، ولا يجعل الاقتصاد الإسلامي قسما من الرأسمالي."},{"h":"أن يكون المقسم موحدا","x":"لا تخلط العلوم باعتبار موضوعها (إنسانية واجتماعية وطبيعية) مع العلوم باعتبار مقصدها (أداتية وغائية)."},{"h":"أن تكون الأقسام شاملة","x":"اللغة العربية نحو وصرف فقط تقسيم ناقص، والسلطة تشريعية وتنفيذية فقط ينقصها القضائية."}]}],"quiz":[{"q":"عرّف أحدهم القتل بأنه «إزهاق الروح بالسكين». ما الشرط الذي اختل؟","o":["أن يكون التعريف جامعا","أن يكون التعريف مانعا","ألا يكون في التعريف تكرار","ألا يكون في التعريف دور"],"why":"مشكلته أنه افتقد أحد شروط التعريف السليم، وهو شرط «الجامعيّة»، فلم يكن جامعاً لجميع أنواع القتل.","pg":68},{"q":"عرّف أحدهم المصرف بأنه «المؤسسة المالية». ما عيب هذا التعريف؟","o":["غير مانع، فتدخل فيه شركات التأمين","غير جامع، فيخرج منه المصرف الإسلامي","فيه دور، فيتوقف على تعريف المال","فيه تكرار، فالمؤسسة هي المالية"],"why":"إذن، حين عرّفنا المصرف بأنه «مؤسسة مالية» ارتكبنا خطأً، والخطأ يكمن في أن تعريفنا غير مانع","pg":69},{"q":"سئلت عن الهاتف النقال فقلت: هو الآيفون. ما خطؤك؟","o":["عرّفته بلفظ أخص منه","عرّفته بلفظ أعم منه","عرّفته بلفظ أخفى منه","عرّفته بلفظ يساويه"],"why":"وإذا عرّفنا الهاتف النقّال بأنه «آيفون» نكون كذلك مخطئين؛ لأنّ لفظ «آيفون» أخص من لفظ «الهاتف النقّال».","pg":75},{"q":"قسّم أحدهم الاقتصاد إلى رأسمالي واشتراكي، وجعل الإسلامي والليبرالي من أقسام الرأسمالي. أين الخلل؟","o":["جعل قسيم الشيء قسما منه","جعل الأقسام شاملة للمقسم","جعل المقسم موحدا في القسمة","جعل للتقسيم ثمرة وفائدة"],"why":"الخطأ أننا جعلنا الاقتصاد الإسلامي قسماً من أقسام الاقتصاد الرأسمالي، في حين هو في الحقيقة قسيماً موازياً له","pg":85},{"q":"عرّف شخص لمن لا يعرف الإجارة بأنها «أن يؤجر الإنسان شيئا إلى آخر مدة محدودة بثمن مقسط». ما الخلل؟","o":["ذكر المعرَّف المجهول في التعريف","وقع في تكرار بين لفظين مترادفين","عرّف الشيء بلفظ أعم منه بكثير","جعل قسيم الشيء قسما من أقسامه"],"why":"لأنّي استعملتُ المعرَّف في التعريف، فأنت لا تعرف معنى الإجارة وأنا ذكرت لك هذا الذي لا تعرفه في التعريف","pg":71}]},{"k":"c10","t":"القضايا وأحكامها","q":"ما أنواع القضايا، ومتى تتناقض قضيتان، وكيف نصوغ النقيض؟","essence":"صنّف القضية ثم ابحث عن نقيضها","kw":["الحملية والشرطية","المسورة والمهملة","التناقض"],"sections":[{"t":"القضية والجملة الخبرية","pg":92,"key":"القضية: «هي الجملة الخبرية سواء أكانت مثبتة أم منفية».","p":["إذن: الجملة الإنشائية: هي التي لا تحتمل الصدق أو الكذب، والجملة الخبرية: هي التي يمكن تكذيبها أو تصديقها."],"items":[{"h":"جمل إنشائية","x":"لا تلعب بالكرة في المساء. هل نجحت في الامتحان؟"},{"h":"جمل خبرية","x":"نجح سعد في اختباراته. الوزير مسافر."}]},{"t":"القضية الحملية والشرطية","pg":95,"key":"القضية الحمليّة: «هي القضية التي نحكم فيها بثبوت شيء لشيء أو نفيه عنه».","p":["إذن: القضية الحمليّة تتكوّن من موضوع ومحمول والرابطة بينهما."],"items":[{"h":"أمثلة حملية","x":"الرأسمالية شر، والرأسمالية ليست صالحة، والمتنبي شاعر، وعمر بن الخطاب ليس بشاعر."},{"h":"الموضوع والمحمول","x":"في «الشافعي عالم»: الشافعي موضوع محكوم عليه، وعالم محمول محكوم به."},{"h":"الشرطية المتصلة","x":"«عبارة عن قضيتين حمليّتين متصلتين ببعضهما، القضية الأولى تُسمّى المقدّم، والقضية الثانية تسمّى التالي». مثال: إذا دخل شهر رمضان يصوم المسلمون."},{"h":"الشرطية المنفصلة","x":"«هي التي حكمنا بأنّ بين مقدّمها وتاليها انفصالاً وتنافياً، أي لا يمكن أن يجتمعا». مثال: العدد إما أن يكون زوجيا أو فرديا."}]},{"t":"أقسام الحملية باعتبار الموضوع وكمه","pg":99,"key":"«ولذلك قلنا: إن القضية المهملة في قوّة القضيّة الجزئية، وليست في قوة القضيّة الكليّة.»","p":[],"items":[{"h":"الشخصية","x":"«هي التي يكون موضوعها مرتبطاً بشخص». مثال: محمد رسول."},{"h":"الطبيعية","x":"«هي التي يكون موضوعها مرتبطاً بالكلّي بقطع النظر عن أفراده ومصاديقه». مثال: الفيلسوف ذكي، العلم نافع."},{"h":"المسورة وأشكالها الأربعة","x":"كلية موجبة: كل السمك يعيش في الماء. كلية سالبة: لا شيء من السمك يعيش في الماء. جزئية موجبة: بعض السمك يعيش في الماء. جزئية سالبة: بعض السمك لا يعيش في الماء."},{"h":"المهملة","x":"«هي القضيّة التي لم يُذكر فيها سور، لا كلّي ولا جزئي». مثال: الليبراليون رأسماليون، والشعراء كاذبون."},{"h":"تطبيقات","x":"«بعض أفراد الشرطة لا يقومون بواجبهم» مسورة جزئية سالبة، و«جميع الشعراء كاذبون» مسورة كلية موجبة."}]},{"t":"أقسامها باعتبار وجود الموضوع والإمكان","pg":105,"key":"«مما مضى يتبيّن لنا: أنّ القضية إذا كان يستحيل وجودها في الواقع فهي قضية ذهنية، وإن كانت موجودة في الواقع فهي القضية الخارجية، وإن لم تكن موجودة في الواقع لكن وجودها ليس محالاً فهي قضية حقيقية.»","p":[],"items":[{"h":"ذهنية وخارجية وحقيقية","x":"شريك لله: ذهنية. ابن سينا ذكي: خارجية. عالم بلا ظلم: حقيقية."},{"h":"المستحيل عقلا","x":"«هو امتناع ثبوت المحمول للموضوع». مثال: خالد يجري جالسا، والأربعة عدد فردي."},{"h":"الواجب عقلا","x":"ما يجب وجوده ولا يجوز عدمه. مثال: العشرة والزوجية."},{"h":"الممكن عقلا","x":"«هو كل شيء لا يترتب على وجوده أو امتناعه محال عقلاً». مثال: وقوع حرب عالمية ثالثة، و«الوقوع دليل الجواز»."}]},{"t":"التناقض وشروطه","pg":110,"key":"التناقض: «هو كون القضيتين لا تجتمعان ولا ترتفعان».","p":["إذن: كل قضيتين يستحيل أن تجتمعا معاً أو أن ترتفعا معاً فإننا نحكم عليهما بأنّهما متناقضتان. وأما إذا لم تقبلا الاجتماع لكنهما تقبلان الافتراق فإنهما من باب التضاد."],"items":[{"h":"نقيضان وضدان","x":"الحياة والموت نقيضان، والأسود والأبيض ضدان لأنه يمكن أن يكون الشيء أحمر."},{"h":"وحدة الموضوع والمحمول","x":"«التعليم ضروري» و«الجامعة ليست ضرورية» لا تتناقضان. و«حاتم كريم» و«حاتم بخيل» ضدان لا نقيضان."},{"h":"الوحدة الزمانية والمكانية","x":"إباحة الخمر وتحريمه في زمنين مختلفين لا تناقض. و«الليبرالية جيدة» في الغرب و«غير جيدة» في العالم الإسلامي لا تناقض."},{"h":"الاتحاد في القوة والفعل","x":"«إنك ميت» بالقوة، و«يا أيها النبي اتق الله» وهو حي بالفعل، فلا تناقض."},{"h":"وحدة القيد","x":"«الديمقراطية تعتمد على المساواة» يقصد بها الاشتراكية، و«لا تعتمد» يقصد بها الليبرالية، فلا تناقض."}]},{"t":"كيفية إيجاد النقيض","pg":116,"key":"«إذن: كل قضية نريد أن ننقضها؛ فقط نقوم بتبديل الكيف والسور إلى نقيضهما.»","p":[],"items":[{"h":"المهملة: تبديل الكيف","x":"الشاعر كاذب، نقيضها: الشاعر غير كاذب. الحج واجب، نقيضها: الحج غير واجب."},{"h":"الكلية الموجبة","x":"كل الطلاب ناجحون، نقيضها: بعض الطلاب ليسوا ناجحين."},{"h":"الكلية السالبة","x":"كل المسيحيين ليسوا بمسلمين، نقيضها: بعض المسيحيين مسلمون."},{"h":"الجزئية الموجبة","x":"بعض المصائب مفيدة، نقيضها: كل المصائب غير مفيدة."},{"h":"مثال ابن تيمية","x":"«جميع عقلاء بني آدم من جميع أصناف المتكلمين في العلم حرروا علومهم بدون المنطق اليوناني» كلية سالبة، يكفي لنقضها عاقل واحد كابن سينا."}]}],"quiz":[{"q":"حدد نوع القضية: «العدد إما أن يكون زوجيا أو فرديا».","o":["شرطية منفصلة","شرطية متصلة","حملية موجبة","حملية سالبة"],"why":"في هذا المثال حكمنا بالتنافي والانفصال بين الزوجيّة والفرديّة، فالعدد إما أن يكون زوجياً أو يكون فردياً، ولا يمكن أن يكون العدد نفسه زوجياً وفردياً.","pg":98},{"q":"حدد نوع القضية «الليبراليون رأسماليون»، وبيّن في قوة أي قضية هي.","o":["مهملة، وهي في قوة الجزئية","مسورة كلية، لأنها تعم الجميع","مهملة، وهي في قوة الكلية","شخصية، لأن موضوعها محدد"],"why":"فإذا قلنا «الليبراليون رأسماليون» فكأنما نقول: «بعض الليبراليين رأسماليون».","pg":101},{"q":"حدد نوع القضية «عالم بلا ظلم» باعتبار تحقق وجود موضوعها.","o":["قضية حقيقية","قضية خارجية","قضية ذهنية","قضية طبيعية"],"why":"وإن لم تكن موجودة في الواقع لكن وجودها ليس محالاً فهي قضية حقيقية.","pg":106},{"q":"ما نقيض قضية «كل الطلاب ناجحون»؟","o":["بعض الطلاب ليسوا ناجحين","كل الطلاب ليسوا ناجحين","بعض الطلاب ناجحون فعلا","لا أحد من الطلاب راسب"],"why":"وإذا جمعنا الأمرين «السلب والجزئية» فإنّ القضية ستكون: «بعض الطلاب ليسوا ناجحين». وهذه هي نقيض القضية الكلية الموجبة «كل الطلاب ناجحون».","pg":118},{"q":"قال قائل: القرآن أباح الخمر، والقرآن حرم الخمر، فهذا تناقض. ما الرد المنطقي؟","o":["لا تناقض، لاختلاف زمن القضيتين","لا تناقض، لاختلاف موضوع القضيتين","هو تناقض حقيقي لاتحاد الموضوع","لا تناقض، لاختلاف مكان القضيتين"],"why":"لأنّ القرآن الكريم أباح الخمر في مرحلة زمانية سابقة ومختلفة عن مرحلة تحريم الخمر، وبما أنّ زمن القضيتين مختلف فإنه لا تناقض.","pg":113}]},{"k":"c11","t":"القياس","q":"ما القياس، ومتى ينتج الشكل الأول نتيجة صحيحة؟","essence":"مقدمتان تلدان نتيجة، وصحة الصورة غير صحة المادة","kw":["الحد الأوسط","الشكل الأول","صورة القياس ومادته"],"sections":[{"t":"تعريف القياس وحدوده","pg":122,"key":"القياس: «هو عبارة عن عدة قضايا متى ما ثبتت لذاتها يلزم عنها نتيجة معيّنة».","p":["فهو سلسلة من المقدمات إن ثبتت صحتها واستوفت شروط القياس فإنها تستلزم نتيجة متولّدة عن تلك المقدمات."],"items":[{"h":"مثال","x":"جاسم قطري (مقدمة صغرى)، وكل قطري غني (مقدمة كبرى)، إذن جاسم غني (نتيجة)."},{"h":"الحد الأصغر","x":"موضوع المقدمة الأولى: «جاسم»."},{"h":"الحد الأكبر","x":"محمول المقدمة الثانية: «غني»."},{"h":"الحد الأوسط","x":"«هو الكلمة المتكررة في المقدمتين، وتكون محمولاً للمقدمة الصغرى، وموضوعاً للمقدمة الكبرى»: «قطري»، ويحذف من النتيجة."},{"h":"مثال آخر","x":"سهيل نجم، وكل نجم في السماء، إذن سهيل في السماء."}]},{"t":"الشكل الأول وشرطاه","pg":124,"key":"«إذن: الشكل الأوّل يشترط شرطين حتى ينتج، شرطٌ متعلّق بالمقدّمة الصغرى (وهو أن تكون موجبة)، وشرطٌ متعلق بالمقدمة الكبرى وهو أن تكون كليّة.»","p":[],"items":[{"h":"لماذا الشكل الأول؟","x":"للقياس أربعة أشكال، واقتصر الكتاب على الأول لأنه الأهم والأكثر استعمالا، وبقية الأشكال تعود إليه."},{"h":"إيجاب الصغرى","x":"«العلم نافع» موجبة، و«العلم غير نافع» سالبة."},{"h":"كلية الكبرى","x":"أن تبدأ بلفظ يدل على الكلية مثل: كل وجميع، فالمهملة أو المسورة بسور غير كلي لا تنتج."}]},{"t":"الأنواع الأربعة المنتجة","pg":125,"key":"«هذه هي الأنواع الأربعة للشكل الأول، وهي جميعها منتجة إذا توافر فيها الشرطان الأساسيان: أن تكون المقدمة الصغرى موجبة وأن تكون المقدمة الكبرى كليّة.»","p":[],"items":[{"h":"كليتان موجبتان","x":"كل صقر له جناحان، وكل ما له جناحان يطير، إذن الصقر يطير."},{"h":"صغرى جزئية موجبة وكبرى كلية موجبة","x":"محمد يوحى إليه، وكل من يوحى إليه نبي، إذن محمد نبي."},{"h":"صغرى جزئية موجبة وكبرى كلية سالبة","x":"تويتر يعين على التواصل الاجتماعي، وكل ما يعين على التواصل الاجتماعي غير سيئ، إذن تويتر غير سيئ."},{"h":"صغرى كلية موجبة وكبرى كلية سالبة","x":"كل أنواع الربا ضارة، وكل ما هو ضار غير مرغوب شرعا، إذن كل أنواع الربا غير مرغوبة شرعا."}]},{"t":"صورة القياس ومادته","pg":126,"key":"«مما مضى نعرف أنّ وظيفة المنطق لا علاقة لها بمادة القياس، وإنما وظيفته متعلقة بصورة القياس الخارجية.»","p":[],"items":[{"h":"صورة ومادة صحيحتان","x":"الطبيب يداوي، وكل من يداوي مفيد، إذن الطبيب مفيد."},{"h":"صورة صحيحة ومادة خاطئة","x":"السحر علم، وكل علم نافع، إذن السحر نافع، وليس صحيحا أن كل علم نافع."}]},{"t":"هل القياس المنطقي مفيد؟","pg":127,"key":"«إذن: نتيجة القياس موجودة ضمنياً في مقدّماته.»","p":["لكن للقياس فائدة من ناحية أخرى، فهو يعيننا على ترتيب الأفكار وتنظيمها، ويساعدنا على وضع أفكارنا في صورة أشكال منضبطة تنتج نتائج قطعية."],"items":[{"h":"الخمر ضار","x":"الخمر ضار، وكل ما هو ضار محرم، فالخمر محرم: ويجب إثبات صحة كل مقدمة حتى يكون القياس صحيحا."},{"h":"الديمقراطية","x":"الديمقراطية تحترم إرادة الشعب، وكل نظام يحترم إرادة الشعب مرغوب، إذن الديمقراطية مرغوبة."}]}],"quiz":[{"q":"في القياس: «سهيل نجم، وكل نجم في السماء، إذن سهيل في السماء»، ما الحد الأوسط؟","o":["نجم، لتكرره في المقدمتين","سهيل، لأنه موضوع الصغرى","في السماء، لأنه محمول الكبرى","سهيل، لأنه موضوع النتيجة"],"why":"حد أوسط: وهو الكلمة المتكررة في المقدمتين، وتكون محمولاً للمقدمة الصغرى، وموضوعاً للمقدمة الكبرى.","pg":122},{"q":"هل ينتج على الشكل الأول قياس مقدمتاه: «جاسم ليس قطريا، وكل قطري غني»؟","o":["لا، لأن المقدمة الصغرى سالبة","نعم، لأن المقدمة الكبرى كلية","لا، لأن المقدمة الكبرى جزئية","نعم، لأن الحد الأوسط متكرر"],"why":"إذن: الشكل الأوّل يشترط شرطين حتى ينتج، شرطٌ متعلّق بالمقدّمة الصغرى (وهو أن تكون موجبة)، وشرطٌ متعلق بالمقدمة الكبرى وهو أن تكون كليّة.","pg":124},{"q":"«السحر علم، وكل علم نافع، إذن السحر نافع». ما الحكم على هذا القياس؟","o":["صورته صحيحة ومادته خاطئة","صورته خاطئة ومادته صحيحة","صورته ومادته صحيحتان معا","صورته ومادته خاطئتان معا"],"why":"صورة القياس صحيحة، فشروط القياس الصحيح تتوافر في هذا القياس، لكن هل مادة القياس صحيحة؟ لا؛ لأنّه ليس صحيحاً أن كل علم نافع","pg":126},{"q":"لماذا يقال إن القياس لا يضيف إلينا معلومة جديدة؟","o":["لأن نتيجته موجودة ضمنيا في مقدماته","لأن مقدماته ظنية لا تفيد القطع","لأن الحد الأوسط يحذف من النتيجة","لأنه يقوم على تتبع بعض الجزئيات"],"why":"إذن: نتيجة القياس موجودة ضمنياً في مقدّماته.","pg":127},{"q":"أراد طالب إثبات أن «الخمر محرم» بقياس منطقي. ما الذي يلزمه حتى يكون قياسه صحيحا؟","o":["أن يثبت صحة كل مقدمة من مقدمتيه","أن يكتفي بصحة الصورة دون المادة","أن يثبت النتيجة أولا ثم المقدمات","أن يجعل المقدمة الصغرى سالبة كلية"],"why":"هنا يجب عليّ حتى يكون قياسي صحيحاً أن أثبت صحة المقدمة الأولى، أي أثبت أن الخمر ضار، وأثبت كذلك صحة المقدمة الثانية وهي أنّ كل ضار محرّم","pg":127}]},{"k":"c12","t":"الاستقراء","q":"كيف نصل إلى حكم كلي من تتبع الجزئيات، وما حدود هذا الطريق؟","essence":"تتبع الجزئيات: قطع بلا جديد، أو ظن مفيد","kw":["الاستقراء التام والناقص","السببية","أوهام الباحثين"],"sections":[{"t":"تعريف الاستقراء","pg":128,"key":"الاستقراء: «هو أن نحكم على كلّي بناءً على وجوده في بعض جزئياته أو كلّها».","p":[],"items":[{"h":"فرق كرة القدم","x":"تابعت خمسين مباراة فوجدت كل فريق من أحد عشر لاعبا، فأصدرت حكما كليا بذلك."},{"h":"النيجيريون","x":"رأيت ألف نيجيري كلهم سود فحكمت بأن كل مواطني نيجيريا سود، ولم تر سوى بعضهم."},{"h":"الأوامر القرآنية","x":"تتبعت كل الأوامر الواردة في القرآن فوجدتها تدل على الوجوب، فحكمت بأن كل أمر قرآني يدل على الوجوب."}]},{"t":"الاستقراء التام والناقص","pg":129,"key":"«إذن: حين نصدر حكمنا بعد أن نطّلع على جميع الجزئيات يكون استقراء تاماً، وحين نصدر حكمنا بعد أن نطلع على بعض الجزئيات يكون استقراءً ناقصاً.»","p":["فأما الاستقراء التام فقد اتفق العلماء على أنه يفيد القطع؛ لأننا استقرينا جميع أفراده فلا مجال للظن. أما الاستقراء الناقص فهو يفيد الظن عند علماء المنطق"],"items":[{"h":"مثال المكتبة","x":"مكتبة فيها ألف كتاب، وجدت تسعمئة منها حمراء فحكمت بأن البقية كذلك: ناقص ظني. فإن أكملت رؤية البقية فهو تام قطعي."}]},{"t":"الانتقادات الموجهة للاستقراء","pg":131,"key":"«خلاصة النقد الموجّه للاستقراء التام أنه على الرغم من أنّه يفيد القطع فإنّه لا يفيدنا بشيء جديد، وإنما يخبرنا فقط بما كنّا نعلم.»","p":[],"items":[{"h":"نقد التام الأول","x":"يكاد يكون متعذرا في الموضوعات الكبرى، فكيف نحصي جميع البشر الذين يمارسون الرياضة؟"},{"h":"نقد التام الثاني","x":"حكمنا بأن أشجار الجزيرة حمراء بعد أن رأيناها جميعا لا يضيف شيئا جديدا."},{"h":"نقد الناقص","x":"أنه حكم على غير معلوم، فما الذي يجعلنا ننطلق من الخاص إلى العام؟ وهي مشكلة تحدث عنها الفيلسوف ديفيد هيوم."},{"h":"مبدأ السببية","x":"إذا تكرر ارتباط شيء بشيء كان أحدهما سببا للآخر، كتعاطي المخدرات والسلوك العدائي، وشرب السم والموت؛ لأن الديمومة تناقض مبدأ الصدفة."}]},{"t":"الاستقراء العلمي","pg":134,"key":"«هذه بعض الطرق التي نستطيع من خلالها أن نتأكد من صحة الفرض المسبّب للظاهرة.»","p":[],"items":[{"h":"مراحله","x":"البحث والملاحظة، ثم وضع الفروض، ثم التحقق."},{"h":"طريقة الاتفاق","x":"مرضى أكلوا أطعمة مختلفة والجامع الوحيد بينهم البرتقال، فهو سبب المرض."},{"h":"طريقة الاختلاف","x":"مريض أكل تفاحة وبرتقالة ومانجو، وسليم أكل تفاحة وبرتقالة فقط، فالسبب المرجح المانجو."},{"h":"طريقة التغير النسبي","x":"قلت جرائم السرقة في البرازيل بعد تحسن الوضع المعيشي، فسوء المعيشة سبب السرقة."}]},{"t":"أوهام الباحثين","pg":136,"key":"«هناك بعض الأوهام التي تنتاب الباحثين وتعتري أعمالهم، يصنّفها الفيلسوف الإنجليزي فرنسيس بيكون إلى أربعة أوهام»","p":[],"items":[{"h":"وهم القبيلة","x":"يتوهم الإنسان صحة أشياء لمجرد أن البيئة الاجتماعية تعتقد صحتها."},{"h":"وهم الكهف","x":"يتبنى الإنسان أفكارا لأنها الأكثر تعبيرا عن رغباته وميوله الخاصة، لا لصحتها."},{"h":"وهم السوق","x":"الاستعمال اللغوي اليومي قد يسبب عدم الدقة في تحديد معاني الألفاظ."},{"h":"وهم المسرح","x":"يردد الباحثون نظريات من سبقهم كالممثل على المسرح، بصرف النظر عن صوابها."}]}],"quiz":[{"q":"مكتبة فيها ألف كتاب، رأيت تسعمئة منها حمراء فحكمت بأن كل كتبها حمراء. ما نوع استقرائك وما حكمه؟","o":["ناقص يفيد الظن","تام يفيد القطع","ناقص يفيد القطع","تام يفيد الظن"],"why":"إن حكمت بذلك فهذا استقراء ناقص، وهو ظنّي","pg":130},{"q":"مرضى أكلوا أطعمة مختلفة، والطعام الوحيد المشترك بينهم البرتقال، فعدّه الباحث سبب المرض. أي طريقة استعمل؟","o":["طريقة الاتفاق","طريقة الاختلاف","التغير النسبي","الاستقراء التام"],"why":"بأن تتفق جميع الحالات المدروسة في سبب واحد، وهذا السبب يكون هو الفرض الصحيح.","pg":134},{"q":"باحث يتبنى فكرة لأنها توافق رغباته وميوله لا لأنها صحيحة. في أي أوهام بيكون وقع؟","o":["وهم الكهف","وهم القبيلة","وهم السوق","وهم المسرح"],"why":"فالإنسان أحياناً يميل إلى تبنّي بعض الأفكار لا لكونها صحيحة في ذاتها، ولكن لكونها الأكثر تعبيراً عن رغباته وميوله الخاصة.","pg":136},{"q":"ما خلاصة النقد الموجه إلى الاستقراء التام؟","o":["يفيد القطع لكنه لا يضيف جديدا","يفيد الظن لأنه يتتبع بعض الأفراد","يضيف جديدا لكنه لا يفيد القطع","يسهل تطبيقه في الظواهر الكبرى"],"why":"خلاصة النقد الموجّه للاستقراء التام أنه على الرغم من أنّه يفيد القطع فإنّه لا يفيدنا بشيء جديد، وإنما يخبرنا فقط بما كنّا نعلم.","pg":132},{"q":"قلت جرائم السرقة في بلد بعد تحسن الوضع المعيشي، فاستنتج الباحث أن سوء المعيشة سبب للسرقة. أي طريقة استعمل؟","o":["التغير النسبي","طريقة الاتفاق","طريقة الاختلاف","الاستقراء التام"],"why":"تعني هذه الطريقة أنّه إذا حصل تغييرٌ في ظاهرةٍ ما، وكان هذا التغيير مرتبطًا بتغيّر في ظاهرةٍ أخرى؛ فإنّ الظاهرة الأولى سببٌ للظاهرة الثانية.","pg":135}]}],"highlights":[{"x":"علم المنطق ليس مصدرًا للأفكار، وإنما هو كاشفٌ عن صحيح الأفكار وفاسدها.","pg":12},{"x":"الجهل المركّب: هو أنك لا تعرف ولا تعرف أنك لا تعرف.","pg":18},{"x":"لا تصدر أحكامًا وتدخل منطقة التصديق إلا بعد أن تضمن أنك مررت بمرحلة التصور.","pg":26},{"x":"قد يكون الأمر ضرورياً عند شخص ونظرياً عند آخر.","pg":27},{"x":"فأحياناً تتحدث عن المفهوم والطرف الآخر يتحدث عن المصداق، ثم تكتشفان أن خلافكما وهمي لا حقيقة له.","pg":37},{"x":"الكليّات ليست درجةً واحدة، وإنما هي درجاتٌ متفاوتة بحسب مستوى شمولها وعمومها.","pg":41},{"x":"المعيار العام للتعريف السليم هو ألا يأتي في ذهن الشخص صورة أخرى غير صورة المعرَّف.","pg":65},{"x":"التقسيم الذي لا تترتب عليه فائدة وثمرة يكون تقسيماً غير معتبر.","pg":85},{"x":"الوقوع دليل الجواز.","pg":108},{"x":"وظيفة المنطق لا علاقة لها بمادة القياس، وإنما وظيفته متعلقة بصورة القياس الخارجية.","pg":127},{"x":"نتيجة القياس موجودة ضمنياً في مقدّماته.","pg":127}],"concepts":[{"term":"علم المنطق","def":"هو قواعد عقليّة تساعد على التصوّر والاستدلال بصورة صحيحة","pg":9},{"term":"العلم عند المناطقة","def":"مطلق الإدراك","pg":15},{"term":"اليقين","def":"هو إدراك الأمر على ما هو عليه إدراكاً جازماً","pg":15},{"term":"الظن","def":"هو الاحتمال الراجح","pg":16},{"term":"الوهم","def":"هو الاحتمال المرجوح","pg":17},{"term":"الجهل البسيط","def":"هو ألا يكون لديك تصوّر أو حكم عن شيء ما","pg":17},{"term":"الجهل المركب","def":"هو إدراك الشيء على خلاف ما هو عليه إدراكاً جازماً","pg":18},{"term":"التصور","def":"هو الإدراك بلا حُكم","pg":20},{"term":"التصديق","def":"هو الإدراك مع حُكم","pg":20},{"term":"الدلالة","def":"الدلالة هي أن يكون الشيء بحالة يلزم من العلم بها العلم بشيء آخر.","pg":28},{"term":"دلالة المطابقة","def":"أن اللفظ يطابق كل معناه مطابقة تامة","pg":33},{"term":"دلالة التضمن","def":"تعني أنّ اللفظ يدل على جزء معناه، ولا يدلّ على كلّ المعنى كدلالة المطابقة.","pg":34},{"term":"دلالة الالتزام","def":"دلالة اللفظ على معنى خارج عن المعنى الموضوع له.","pg":35},{"term":"المفهوم","def":"الصورة الذهنية عن الأشياء","pg":36},{"term":"المصداق","def":"ما ينطبق عليه المفهوم في الواقع","pg":36},{"term":"الجنس","def":"هو الكلّي الذي يصدق على أفراد مختلفة الحقائق","pg":60},{"term":"النوع","def":"هو المفهوم الكلي الذي يتفق أفراده في الحقيقة","pg":61},{"term":"الفصل","def":"هو المفهوم الكلي الذي يميّز النوع عن بقية الأنواع","pg":61},{"term":"العرض العام","def":"هو الكلي الذي ليس من ماهية الشيء وإنما يعرض عليه وعلى غيره","pg":62},{"term":"الدور","def":"توقّف وجود الشيء على ما يتوقف وجوده عليه","pg":73},{"term":"القضية","def":"هي الجملة الخبرية سواء أكانت مثبتة أم منفية","pg":92},{"term":"القضية الحملية","def":"هي القضية التي نحكم فيها بثبوت شيء لشيء أو نفيه عنه","pg":95},{"term":"التناقض","def":"هو كون القضيتين لا تجتمعان ولا ترتفعان","pg":110},{"term":"القياس","def":"هو عبارة عن عدة قضايا متى ما ثبتت لذاتها يلزم عنها نتيجة معيّنة","pg":122},{"term":"الاستقراء","def":"هو أن نحكم على كلّي بناءً على وجوده في بعض جزئياته أو كلّها","pg":128}],"links":[{"topic":"التفكير النقدي","pg":12},{"topic":"الحوار وإدارة النقاش","pg":26},{"topic":"الديمقراطية والنظم السياسية","pg":37},{"topic":"صياغة التعريفات والمفاهيم","pg":65},{"topic":"أصول الفقه","pg":11},{"topic":"فهم دلالات النص القرآني","pg":35},{"topic":"المنهج العلمي والبحث","pg":134},{"topic":"السببية والصدفة","pg":133},{"topic":"التحيز المعرفي","pg":136}]};
